"""Export or verify the authoritative OpenAPI document generated by FastAPI."""
from __future__ import annotations
import argparse
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
DEFAULT_OUTPUT = ROOT.parent / "docs" / "api" / "openapi.runtime.v1.json"
sys.path.insert(0, str(ROOT))


def render_openapi(document: dict) -> str:
    """Stable JSON representation suitable for source control and diff review."""
    return json.dumps(document, ensure_ascii=False, indent=2, sort_keys=True) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument("--check", action="store_true", help="Fail if the committed snapshot is stale.")
    args = parser.parse_args()
    from app.main import app
    expected = render_openapi(app.openapi())
    output = args.output.resolve()
    if args.check:
        if not output.is_file():
            print(f"OpenAPI snapshot missing: {output}", file=sys.stderr)
            return 2
        actual = output.read_text(encoding="utf-8")
        if actual != expected:
            print(f"OpenAPI snapshot is stale: {output}", file=sys.stderr)
            return 1
        print(f"OpenAPI snapshot current: {output}")
        return 0
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(expected, encoding="utf-8")
    print(f"Wrote {len(app.openapi().get('paths', {}))} paths to {output}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
